import numpy as np
import pandas as pd

name = "SparseArray(np.array([1, 0, 0], dtype=subtype), fill_value=0).astype(pd.SparseDtype(subtype, pd.NA)); any/all(skipna=False) for subtype in int64, uint64, float64, complex128, m8[ns]"

results = {}
subtypes = [np.int64, np.uint64, np.float64, np.complex128, 'm8[ns]']

try:
    for subtype in subtypes:
        if subtype == 'm8[ns]':
            arr = np.array([1, 0, 0], dtype=subtype)
            sparse = pd.arrays.SparseArray(arr, fill_value=0)
            sparse_cast = sparse.astype(pd.SparseDtype(subtype, pd.NA))
            any_res = sparse_cast.any(skipna=False)
            all_res = sparse_cast.all(skipna=False)
        else:
            arr = np.array([1, 0, 0], dtype=subtype)
            sparse = pd.arrays.SparseArray(arr, fill_value=0)
            sparse_cast = sparse.astype(pd.SparseDtype(subtype, pd.NA))
            any_res = sparse_cast.any(skipna=False)
            all_res = sparse_cast.all(skipna=False)
        results[str(subtype)] = {"any": any_res, "all": all_res}
    probe(name, results)
except Exception as e:
    probe_exception(name, e)

